// Reliability detail #3: validate the response BEFORE trusting it.
// The most dangerous failure mode is not an error — it is a call
// that 'succeeds' but returns empty or malformed data, which then
// flows downstream and silently corrupts the report. We check shape
// explicitly and flag it, rather than assuming a 200 means good data.
const body = $input.first().json;
const items = Array.isArray(body?.products) ? body.products : null;

const validation = {
  ok: false,
  reason: '',
};

if (!items) {
  validation.reason = 'Response missing expected products array';
} else if (items.length === 0) {
  validation.reason = 'Response returned zero rows (possible upstream outage)';
} else {
  validation.ok = true;
}

// Compute a small piece of analysis + a low-stock flag list.
// (Generic demo logic — mirrors a real reporting/anomaly step.)
const LOW_STOCK_THRESHOLD = 20;
const rows = (items || []).map(p => ({
  id: p.id,
  title: p.title,
  stock: p.stock,
  price: p.price,
  lowStock: typeof p.stock === 'number' && p.stock < LOW_STOCK_THRESHOLD,
}));
const lowStockCount = rows.filter(r => r.lowStock).length;

return [{ json: { validation, rowCount: rows.length, lowStockCount, rows } }];

// Build the report payload. In a real build this feeds an Excel/Sheet
// writer + an email/Slack delivery step. Kept as a plain payload here
// so the demo needs zero credentials to import and inspect.
const d = $input.first().json;
const summary = `Daily report: ${d.rowCount} items, ${d.lowStockCount} low on stock.`;
return [{ json: { summary, generatedAt: new Date().toISOString(), ...d } }];

// Reliability detail #4: failures and bad data are LOUD, not silent.
// Both the API-error output and the failed-validation branch land here,
// where a real build fires a Slack/email alert so the team finds out
// immediately instead of discovering a stale report days later.
const item = $input.first().json;
const reason = item?.validation?.reason
  || item?.error?.message
  || 'Upstream fetch failed after retries';
return [{ json: { alert: true, reason, at: new Date().toISOString() } }];
